from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string")

    paren_string = paren_string.replace(" ", "")
    result = []
    start = 0
    balance = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        else:
            raise ValueError(f"Invalid character encountered: {char}")

        if balance < 0:
            raise ValueError("Unbalanced parentheses: too many closing parentheses")

        if balance == 0:
            result.append(paren_string[start:i + 1])
            start = i + 1

    if balance != 0:
        raise ValueError("Unbalanced parentheses: unclosed groups remaining")

    return result

