from typing import List
def below_zero(operations: List[int]) -> bool:
    if not isinstance(operations, list):
        raise TypeError("operations must be a list")

    balance = 0
    for op in operations:
        if type(op) not in (int, float):
            raise TypeError("operations must contain only numbers")
        if op * 0 != 0:
            raise ValueError("operations must contain finite numbers")

        balance += op
        if balance < 0:
            return True

    return False

from typing import List
def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")
    if threshold < 0:
        return False
    if len(numbers) < 2:
        return False

    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if sorted_nums[i+1] - sorted_nums[i] < threshold:
            return True
    return False

from typing import List
def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if type(numbers) is not list:
        raise TypeError("numbers must be a list")
    if type(delimeter) is not int:
        raise TypeError("delimeter must be an integer")

    if not numbers:
        return []

    for x in numbers:
        if type(x) is not int:
            raise TypeError("elements of numbers must be integers")

    result = [delimeter] * (len(numbers) * 2 - 1)
    result[0::2] = numbers
    return result

from typing import List
def parse_nested_parens(paren_string: str) -> List[int]:
    if type(paren_string) is not str:
        raise TypeError("Input must be a string")

    result = []
    for group in paren_string.split():
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError("Unbalanced parentheses: too many closing parentheses")
            else:
                raise ValueError(f"Invalid character found: {char}")

        if current_depth != 0:
            raise ValueError("Unbalanced parentheses: unclosed parentheses")

        result.append(max_depth)

    return result

