from typing import List, Tuple
def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if type(numbers) is not list:
        raise TypeError("numbers must be a list")

    sum_val = 0
    prod_val = 1

    for n in numbers:
        if type(n) is not int:
