        sum_val += n
        prod_val *= n

    return sum_val, prod_val

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    if type(a) is not str or type(b) is not str:
        raise TypeError("Inputs must be strings")
    if len(a) != len(b):
        raise ValueError("Inputs must be of the same length")

    result = []
    for x, y in zip(a, b):
        if x not in '01' or y not in '01':
            raise ValueError("Inputs must consist only of 1s and 0s")
        result.append('1' if x != y else '0')

    return ''.join(result)

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if type(n) is not int:
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    return ' '.join(map(str, range(n + 1)))

def count_distinct_characters(string: str) -> int:
    """ Given a string, find out how many distinct characters (regardless of case) does it consist of
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
    """
    if type(string) is not str:
        raise TypeError("Input must be a string")
    return len(set(string.lower()))

def sort_numbers(numbers: str) -> str:
    """ Input is a space-delimited string of numberals from 'zero' to 'nine'.
    Valid choices are 'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight' and 'nine'.
    Return the string with numbers sorted from smallest to largest
    >>> sort_numbers('three one five')
    'one three five'
    """
    if type(numbers) is not str:
        raise TypeError("Input must be a string")

    value_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    try:
        return ' '.join(sorted(numbers.split(), key=value_map.__getitem__))
    except KeyError as e:
        raise ValueError(f"Invalid number word found: {e.args[0]}")

